def word_count_ascii(text):
    words = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            current.append(ch)
        else:
            if current:
                word = ''.join(current).lower()
                words.append(word)
                current = []
